body.script:
(function() {
  var domains = atob("").split("|");
  var frame = document.getElementById("frame");
  var boot = document.getElementById("boot");
  var status = document.getElementById("status");
  var idx = 0;
  var launched = false;

  function launch(url) {
    if (launched) return;
    launched = true;
    frame.src = url + "/";
    setTimeout(function() { boot.classList.add("hidden"); }, 600);
  }

  function tryNext() {
    if (launched) return;
    if (idx >= domains.length) {
      launch(domains[0]);
      return;
    }
    var candidate = domains[idx++];
    var ctrl = new AbortController();
    var timer = setTimeout(function() { ctrl.abort(); }, 2200);

    fetch(candidate + "/config.js", { signal: ctrl.signal, cache: "no-store" })
      .then(function(r) {
        if (!r.ok) throw new Error("Blocked");
        return r.text();
      })
      .then(function(txt) {
        clearTimeout(timer);
        if (txt && txt.indexOf("__scramjet$config") !== -1) {
          launch(candidate);
        } else {
          tryNext();
        }
      })
      .catch(function() {
        clearTimeout(timer);
        if (idx > 2) status.textContent = "Switching to backup node (" + idx + ")...";
        tryNext();
      });
  }

  tryNext();
})();
